import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { BargeInEventInfo } from "./BargeInEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const event: ConversationEvent = {
  __typename: "ConversationEvent",
  id: "1",
  conversationEventType: ConversationEventType.UserBargeIn,
  actionText: "",
  flowId: "",
  slotValue: null,
  stepId: "",
  timestamp: new Date().toISOString(),
  originalTimestamp: 0,
  metadata: {
    parseData: {},
    barge_in_verdict: {
      accepted: true,
      reason: "word_threshold_reached",
      metadata: { word_count: 3 },
    },
    playback: {
      acknowledged_intermediate_markers: [{ kind: "audio_elapsed", offset_ms: 2000 }],
      total_audio_duration_ms: 8400,
    },
  },
};

describe("BargeInEventInfo", () => {
  it("shows playback and decision details", () => {
    renderWithProviders(<BargeInEventInfo event={event} onClose={vi.fn()} />);

    expect(screen.getByText("User interrupted playback")).toBeInTheDocument();
    expect(screen.getByText("2.0 s")).toBeInTheDocument();
    expect(screen.getByText("8.4 s")).toBeInTheDocument();
    expect(screen.getByText("word_threshold_reached")).toBeInTheDocument();
  });

  it("shows the interrupted word when playback recorded one", () => {
    const eventAtWord: ConversationEvent = {
      ...event,
      metadata: {
        ...event.metadata,
        playback: {
          acknowledged_intermediate_markers: [{ kind: "word", offset_ms: 4200 }],
          interrupted_word: "transactions.",
          interrupted_word_index: 58,
          response_word_count: 105,
          total_audio_duration_ms: 8400,
        },
      },
    };

    renderWithProviders(<BargeInEventInfo event={eventAtWord} onClose={vi.fn()} />);

    expect(screen.getByText("transactions.")).toBeInTheDocument();
    expect(screen.getByText("59 of 105")).toBeInTheDocument();
  });

  it("shows fallbacks when playback and verdict metadata are absent", () => {
    const eventWithoutPlayback: ConversationEvent = {
      ...event,
      metadata: { parseData: {} },
    };

    renderWithProviders(<BargeInEventInfo event={eventWithoutPlayback} onClose={vi.fn()} />);

    expect(screen.getAllByText("Unavailable")).toHaveLength(2);
    expect(screen.getByText("Unknown — generation was interrupted")).toBeInTheDocument();
    expect(screen.queryByText("Recognized words")).not.toBeInTheDocument();
  });
});
